const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Lake Erie geometry
  const lakeErie = ee.Geometry.Polygon([
    [[-83.5, 41.3], [-82.5, 41.3], [-78.8, 42.9], 
     [-78.8, 42.9], [-79.0, 43.0], [-81.0, 43.0], 
     [-83.5, 41.8], [-83.5, 41.3]]
  ]);

  // Define dates
  const date1 = '2014-01-09';
  const date2 = '2014-01-14';

  // Try MODIS Terra Snow Cover Daily
  const getSnowCover = (date) => {
    const nextDay = ee.Date(date).advance(1, 'day').format('YYYY-MM-dd').getInfo();
    return ee.ImageCollection('MODIS/006/MOD10A1')
      .filterBounds(lakeErie)
      .filterDate(date, nextDay)
      .select('NDSI_Snow_Cover');
  };

  const col1 = getSnowCover(date1);
  const col2 = getSnowCover(date2);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Jan 9 images: ${size1}`);
  console.log(`Jan 14 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    // Try Landsat 8 as fallback
    const getLandsat = (date) => {
      const nextDay = ee.Date(date).advance(1, 'day').format('YYYY-MM-dd').getInfo();
      return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(lakeErie)
        .filterDate(date, nextDay);
    };

    const l8_col1 = getLandsat(date1);
    const l8_col2 = getLandsat(date2);
    const l8_size1 = l8_col1.size().getInfo();
    const l8_size2 = l8_col2.size().getInfo();

    console.log(`Landsat fallback - Jan 9: ${l8_size1}, Jan 14: ${l8_size2}`);

    if (l8_size1 === 0 || l8_size2 === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Process MODIS snow cover
  const img1 = col1.first();
  const img2 = col2.first();

  // NDSI_Snow_Cover: 0-100 = NDSI snow cover, 200=missing, 201=no decision, 
  // 239=ocean, 250=cloud, 254=detector saturated, 255=fill
  // Ice/Snow pixels are those with NDSI_Snow_Cover between 10-100
  const getIceMask = (img) => {
    const snowCover = img.select('NDSI_Snow_Cover');
    return snowCover.gte(10).and(snowCover.lte(100));
  };

  const iceMask1 = getIceMask(img1);
  const iceMask2 = getIceMask(img2);

  // Calculate ice extent (area in square meters)
  const calcIceExtent = (mask) => {
    const pixelArea = mask.multiply(ee.Image.pixelArea());
    return pixelArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeErie,
      scale: 500,
      maxPixels: 1e9
    });
  };

  const result1 = calcIceExtent(iceMask1);
  const result2 = calcIceExtent(iceMask2);

  const extent1 = result1.get('NDSI_Snow_Cover').getInfo();
  const extent2 = result2.get('NDSI_Snow_Cover').getInfo();

  // Check pixel counts
  const count1 = iceMask1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeErie,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  const count2 = iceMask2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeErie,
    scale: 500,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  console.log(`Jan 9: Ice extent = ${(extent1/1e6).toFixed(2)} km², Pixels = ${count1}`);
  console.log(`Jan 14: Ice extent = ${(extent2/1e6).toFixed(2)} km², Pixels = ${count2}`);

  if (extent1 === null || extent2 === null || extent1 === undefined || extent2 === undefined) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (count1 === 0 && count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Compare ice extents - did it DECREASE on Jan 14 vs Jan 9?
  if (extent2 < extent1) {
    console.log('Ice extent decreased from Jan 9 to Jan 14');
    console.log('<answer>A</answer>');
  } else {
    console.log('Ice extent did not decrease (stayed same or increased)');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
